async def act(page):
    """
    From the current 'New Rule / Magento Admin' page state, open the Actions tab, set a fixed $40 discount
    for the whole cart (applies to all customers), and save the rule.

    This function performs only new interactions from the current UI state.
    """
    import asyncio

    # 1) Open the Actions tab using the exact accessible link text from the accessibility tree first,
    #    then fall back to a simpler 'Actions' link if necessary.
    long_actions_name = (
        "The information in this tab has been changed. This tab contains invalid data. Please solve the problem before saving. Actions"
    )
    try:
        await page.get_by_role("link", name=long_actions_name).click()
    except Exception:
        try:
            await page.get_by_role("link", name="Actions").click()
        except Exception:
            # If clicking the tab fails, fields may already be visible; continue.
            pass

    # brief pause to allow the Actions tab contents to render
    await asyncio.sleep(0.5)

    # 2) Set 'Apply' to a fixed-amount-for-whole-cart option.
    apply_options = [
        "Fixed amount discount for whole cart",
        "Fixed Amount Discount for whole cart",
        "Fixed amount discount",
        "Fixed Amount Discount",
        "Fixed amount for whole cart",
    ]
    applied = False
    for opt in apply_options:
        if applied:
            break
        try:
            await page.get_by_label("Apply").select_option({"label": opt})
            applied = True
            break
        except Exception:
            try:
                await page.get_by_label("Apply *").select_option({"label": opt})
                applied = True
                break
            except Exception:
                continue

    # 3) Fill Discount Amount with 40 (fixed $40 discount)
    for dlabel in ("Discount Amount", "Discount amount", "Discount"):
        try:
            await page.get_by_label(dlabel).fill("40")
            break
        except Exception:
            continue

    # 4) Save the rule. This will submit the form and may navigate; make it the last action.
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        for name in ("Save Rule", "Save and Continue Edit"):
            try:
                await page.get_by_role("button", name=name).click()
                break
            except Exception:
                continue

    # Do not interact with the page after clicking Save (it may navigate).

